import Foundation

/// One imported building mesh and the scale it should be placed at.
struct BuildingAsset {
    let path: String
    let scale: Float
}

/// The building pool. Variants are generated by `Scripts/build_variants.py`;
/// eras without a generated set fall back to the closest one.
enum BuildingCatalog {
    static let roundhouse = BuildingAsset(path: "roundhouse", scale: 0.85)
    static let roundhouseLarge = BuildingAsset(path: "roundhouse", scale: 1.0)

    static let neolithic: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/neolithic-%02d", $0), scale: 1.12)
    }
    static let bronze: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/bronze-%02d", $0), scale: 1.0)
    }
    static let classical: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/classical-%02d", $0), scale: 1.0)
    }
    static let medieval: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/medieval-%02d", $0), scale: 1.0)
    }
    static let industrial: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/industrial-%02d", $0), scale: 1.0)
    }
    static let modern: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/modern-%02d", $0), scale: 1.0)
    }
    static let renaissance: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/renaissance-%02d", $0), scale: 1.0)
    }
    static let information: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/information-%02d", $0), scale: 1.0)
    }
    static let future: [BuildingAsset] = (1...30).map {
        BuildingAsset(path: String(format: "variants/future-%02d", $0), scale: 1.0)
    }

    static let tower = BuildingAsset(path: "modern-tower", scale: 0.95)

    private static var footprints: [String: SIMD2<Float>] = [:]

    /// Footprint of a mesh in its authored units, cached after the first read.
    static func footprint(for path: String) -> SIMD2<Float> {
        if let cached = footprints[path] { return cached }
        var result = SIMD2<Float>(12, 11)
        if let bounds = try? CivMesh.bounds(named: path + ".civmesh") {
            result = SIMD2(max(bounds.max.x - bounds.min.x, 0.1),
                           max(bounds.max.z - bounds.min.z, 0.1))
        }
        footprints[path] = result
        return result
    }

    /// The main housing pool for an era.
    static func assets(for era: Era) -> [BuildingAsset] {
        switch era {
        case .neolithic:
            return neolithic
        case .bronze:
            return bronze
        case .classical:
            return classical
        case .medieval:
            return medieval
        case .renaissance:
            return renaissance
        case .industrial:
            return industrial
        case .modern:
            return modern + [tower]
        case .information:
            return information
        case .future:
            return future
        }
    }

    /// Building variants that suit a district.
    ///
    /// The generated sheets are ordered, so a stable fraction of each era's
    /// pool is assigned to each district. This keeps every era deterministic
    /// and gives civic and industrial plots a visibly different silhouette
    /// without needing per-mesh metadata.
    static func assets(for era: Era, district: District) -> [BuildingAsset] {
        let pool = assets(for: era)
        guard !pool.isEmpty else { return pool }

        let range: Range<Int>
        switch district {
        case .residential:
            range = 0..<Int(Float(pool.count) * 0.50)
        case .commercial:
            range = Int(Float(pool.count) * 0.50)..<Int(Float(pool.count) * 0.70)
        case .civic:
            range = Int(Float(pool.count) * 0.70)..<Int(Float(pool.count) * 0.84)
        case .industrial, .port:
            range = Int(Float(pool.count) * 0.84)..<Int(Float(pool.count) * 0.94)
        case .agricultural, .extractive:
            range = Int(Float(pool.count) * 0.94)..<pool.count
        case .park:
            return []
        }

        let lower = min(max(range.lowerBound, 0), pool.count - 1)
        let upper = min(max(range.upperBound, lower + 1), pool.count)
        let slice = Array(pool[lower..<upper])
        return slice.isEmpty ? pool : slice
    }

    /// A smaller pool of older housing that survives into the era.
    static func survivors(for era: Era) -> [BuildingAsset] {
        switch era {
        case .neolithic:
            return []
        case .bronze:
            return neolithic
        case .classical:
            return bronze
        case .medieval:
            return classical
        case .renaissance:
            return medieval
        case .industrial:
            return renaissance
        case .modern:
            return industrial
        case .information:
            return modern
        case .future:
            return information
        }
    }

    /// Unique asset paths in use, for the renderer to load once.
    static let allPaths: [String] = {
        var seen = Set<String>()
        var paths: [String] = []
        for era in Era.allCases {
            for asset in assets(for: era) + survivors(for: era) {
                if seen.insert(asset.path).inserted {
                    paths.append(asset.path)
                }
            }
        }
        return paths
    }()
}
